-- SAP S/4HANA -> canonical INVOICE_LINE (SAP_B). Generated by tools/build_silver_sql.py.
SELECT 'SAP_B' AS SOURCE_SLOT, 'SAP S/4HANA' AS SOURCE_SYSTEM, k.BUKRS AS COMPANY_CODE, k.BELNR AS INVOICE_ID, r.EBELN AS PO_NUMBER, r.EBELP::STRING AS PO_ITEM, k.LIFNR AS SUPPLIER_ID,
  k.BLDAT AS INVOICE_DATE, r.MENGE AS INV_QTY, r.WRBTR AS INV_AMOUNT, k.WAERS AS CURRENCY
FROM {{ source('src_s4_b', 'rseg') }} r JOIN {{ source('src_s4_b', 'rbkp') }} k ON k.BELNR = r.BELNR AND k.GJAHR = r.GJAHR
